mapper.sql:
AND problem_id IN (
	SELECT problem_id
	FROM voj_problems
	WHERE problem_status = 'PUBLISHED'
)
AND (
	uid = #{viewerUid}
	OR NOT EXISTS (
		SELECT 1
		FROM voj_contest_submissions running_cs
		JOIN voj_contests running_c ON running_c.contest_id = running_cs.contest_id
		WHERE running_cs.submission_id = voj_submissions.submission_id
		AND running_c.contest_end_time > #{now}
	)
)

mapper.select:
SELECT COUNT(*) 
FROM voj_submissions 


		submission_submit_time >= #{startTime}


		AND submission_submit_time < #{endTime}

SELECT COUNT(*) 
FROM voj_submissions 
NATURAL JOIN voj_users 


		problem_id = #{problemId}


		AND username = #{username}


		AND submission_judge_result = #{judgeResult}

SELECT EXTRACT(YEAR_MONTH FROM submission_submit_time) AS month, COUNT(*) as submissions 
FROM `voj_submissions`
WHERE submission_submit_time >= #{startTime} AND submission_submit_time < #{endTime}

	AND uid = #{uid}


	AND submission_judge_result = 'AC'

GROUP BY EXTRACT(YEAR_MONTH FROM submission_submit_time)

SELECT DATE(submission_submit_time) AS date, COUNT(*) as submissions 
FROM `voj_submissions`
WHERE submission_submit_time >= #{startTime} AND submission_submit_time < #{endTime}

	AND uid = #{uid}


	AND submission_judge_result = 'AC'


GROUP BY DATE(submission_submit_time)

SELECT COUNT(*)
FROM voj_submissions
WHERE language_id = #{languageId}

SELECT * 
FROM voj_submissions 
WHERE submission_id = #{submissionId}

SELECT submission_execute_time
FROM voj_submissions
WHERE submission_id = #{submissionId}

SELECT * 
FROM voj_submissions 
NATURAL JOIN voj_users 


		problem_id = #{problemId}


		AND username = #{username}





ORDER BY submission_id DESC 
LIMIT #{limit}

SELECT *
FROM voj_submissions
NATURAL JOIN voj_users


		problem_id = #{problemId}


		AND username = #{username}


		AND submission_judge_result = #{judgeResult}


ORDER BY submission_id DESC
LIMIT #{offset}, #{limit}

SELECT * 
FROM voj_submissions 
NATURAL JOIN voj_users 
WHERE submission_id <= #{submissionId} 

	AND problem_id = #{problemId} 


	AND username = #{username}


	AND submission_judge_result = #{judgeResult}




ORDER BY submission_id DESC
LIMIT #{limit}

SELECT * 
FROM voj_submissions 
NATURAL JOIN voj_users 
WHERE submission_id >= #{submissionId} 

	AND problem_id = #{problemId} 


	AND username = #{username} 




ORDER BY submission_id 
LIMIT #{limit}

SELECT * 
FROM voj_submissions 
WHERE problem_id = #{problemId} AND uid = #{uid} 
ORDER BY submission_id DESC 
LIMIT #{limit}
